#[test]
fn worker_prompt_draft_tracks_line_editing_until_enter() {
    let mut draft = String::new();
    let mut cursor = 0;
    let mut is_prompt = false;

    assert_eq!(
        update_worker_prompt_draft_for_key(
            &mut draft,
            &mut cursor,
            &mut is_prompt,
            KeyEvent::new(KeyCode::Char('f'), KeyModifiers::empty()),
            true,
        ),
        None
    );
    update_worker_prompt_draft_for_key(
        &mut draft,
        &mut cursor,
        &mut is_prompt,
        KeyEvent::new(KeyCode::Char('x'), KeyModifiers::empty()),
        true,
    );
    update_worker_prompt_draft_for_key(
        &mut draft,
        &mut cursor,
        &mut is_prompt,
        KeyEvent::new(KeyCode::Backspace, KeyModifiers::empty()),
        true,
    );
    update_worker_prompt_draft_for_key(
        &mut draft,
        &mut cursor,
        &mut is_prompt,
        KeyEvent::new(KeyCode::Char('i'), KeyModifiers::empty()),
        true,
    );
    update_worker_prompt_draft_for_key(
        &mut draft,
        &mut cursor,
        &mut is_prompt,
        KeyEvent::new(KeyCode::Char('x'), KeyModifiers::empty()),
        true,
    );
    update_worker_prompt_draft_for_key(
        &mut draft,
        &mut cursor,
        &mut is_prompt,
        KeyEvent::new(KeyCode::Char(' '), KeyModifiers::empty()),
        true,
    );
    update_worker_prompt_draft_for_key(
        &mut draft,
        &mut cursor,
        &mut is_prompt,
        KeyEvent::new(KeyCode::Char('i'), KeyModifiers::empty()),
        true,
    );
    update_worker_prompt_draft_for_key(
        &mut draft,
        &mut cursor,
        &mut is_prompt,
        KeyEvent::new(KeyCode::Char('t'), KeyModifiers::empty()),
        true,
    );

    assert_eq!(
        update_worker_prompt_draft_for_key(
            &mut draft,
            &mut cursor,
            &mut is_prompt,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::empty()),
            true,
        )
        .as_deref(),
        Some("fix it")
    );
    assert!(draft.is_empty());
    assert_eq!(cursor, 0);
}

