#[test]
fn finished_agent_does_not_reopen_on_repaint() {
    // The flicker: highlighting a done agent triggers a resize/repaint -> output,
    // which previously flipped done -> in-progress. Output with no user input
    // since completion must NOT re-open the agent; input after completion does.
    let done = Instant::now();
    // No input at all -> repaint, stays done.
    assert!(!post_completion_output_is_new_turn(None, Some(done)));
    // Input BEFORE completion (the original turn) -> still just a repaint.
    let before = done.checked_sub(Duration::from_secs(5)).unwrap_or(done);
    assert!(!post_completion_output_is_new_turn(
        Some(before),
        Some(done)
    ));
    // Input AFTER completion -> a genuine new turn, re-open as in-progress.
    let after = done + Duration::from_secs(1);
    assert!(post_completion_output_is_new_turn(Some(after), Some(done)));
}

#[test]
fn busy_spinner_reopens_a_falsely_completed_agent() {
    // A reappearing spinner proves the agent is still working: reopen even with
    // no user input (mis-detected completion during an inter-step lull).
    let busy: Vec<String> = vec![
        "Editing src/main.rs".to_string(),
        "> ".to_string(),
        "* Cogitating... (12s \u{00b7} esc to interrupt)".to_string(),
        "  bypass permissions on (shift+tab to cycle)".to_string(),
    ];
    assert!(recent_lines_look_busy(&busy));

    // The idle resize/repaint that caused the old flicker shows NO spinner, so it
    // must NOT reopen a finished agent.
    let idle: Vec<String> = vec![
        "Edited 3 files".to_string(),
        "> ".to_string(),
        "  bypass permissions on (shift+tab to cycle)".to_string(),
    ];
    assert!(!recent_lines_look_busy(&idle));
}

#[test]
fn key_choices_read_as_buttons_not_prose() {
    // A confirm dialogue's keys are the one thing that must be unmissable, so they
    // render bracketed and in the accent colour, ahead of any explanation.
    let line = key_choice_line(&[("y", "merge"), ("Esc", "cancel")]);
    let text: String = line.spans.iter().map(|s| s.content.as_ref()).collect();
    assert_eq!(text, "  [y] merge     [Esc] cancel");

    let keys: Vec<&str> = line
        .spans
        .iter()
        .filter(|span| span.style.fg == Some(ACCENT))
        .map(|span| span.content.as_ref())
        .collect();
    assert_eq!(keys, vec!["y", "Esc"], "every key is accent-coloured");
    // Thin theme: emphasis is by colour, not weight.
    assert!(line
        .spans
        .iter()
        .all(|span| !span.style.add_modifier.contains(Modifier::BOLD)));
}

#[test]
fn the_merge_dialogue_always_shows_which_key_confirms() {
    // The modal was sized by Line COUNT while rendering with wrapping, so the long
    // explanation and the dirty-checkout warning pushed the key hint off the
    // bottom: it asked for confirmation without ever saying that `y` confirms.
    let mut app = App::new();
    app.merge_confirm = Some(MergeConfirmation {
        intent: MergeIntent::Selected {
            id: "run-1".to_string(),
            task: "build the thread replay".to_string(),
        },
        detail: Some(
            "your uncommitted local changes merge too (12 files changed, 400 insertions(+), 120 deletions(-))"
                .to_string(),
        ),
    });

    let area = Rect::new(0, 0, 80, 24);
    let mut terminal =
        ratatui::Terminal::new(ratatui::backend::TestBackend::new(80, 24)).expect("test backend");
    terminal
        .draw(|frame| render_merge_prompt(frame, area, &app))
        .expect("draw merge prompt");
    let text: String = terminal
        .backend()
        .buffer()
        .content()
        .iter()
        .map(|cell| cell.symbol())
        .collect();

    assert!(text.contains("Confirm merge"), "modal is titled");
    assert!(
        text.contains("y merges") && text.contains("Esc cancels"),
        "the keys are on the border, where a clipped body cannot hide them"
    );
    assert!(
        text.contains("[y] merge") && text.contains("[Esc] cancel"),
        "and the choices render as buttons inside the body, above the explanation"
    );
    assert!(
        text.contains("uncommitted local changes"),
        "the warning that made the modal overflow is still shown"
    );
}

