#[test]
fn a_main_row_renames_like_any_other() {
    // Field report: r on a main-session row said "rename disabled". The
    // rename only touches task_summary and the saved record — both of which
    // main rows have — so the refusal guarded nothing.
    let mut app = App::new();
    let mut main = test_agent_run("run-main", "long-lived main chat");
    main.mode = AgentMode::Main;
    main.workspace_path = None;
    app.agents.push(main);
    app.selected_agent = 0;

    app.start_rename_selected_agent();
    assert!(
        app.rename_input.is_some(),
        "rename opens on a main row instead of refusing: {:?}",
        app.notice
    );
    app.rename_input = Some("ops copilot".to_string());
    // The box has to be on screen: a main row used to draw its old summary
    // over it, so the rename worked but nobody could see what they typed.
    let screen = render_screen(&mut app, 120, 40);
    assert!(screen.contains("✎ ops copilot"), "rename box not shown:\n{screen}");
    app.commit_rename();
    assert_eq!(app.agents[0].task_summary, "ops copilot");

    // The run's haiku title arrives after the user already named it.
    app.task_summary_tx
        .send(TaskSummaryResult {
            run_id: "run-main".to_string(),
            title: Some("Long-lived main chat".to_string()),
        })
        .unwrap();
    app.poll_task_summary_workers();
    assert_eq!(app.agents[0].task_summary, "ops copilot");
}

#[test]
fn a_stopped_dependency_stalls_the_plan_out_loud() {
    // ~/code/battery: the user stopped n1/n2, so n3/n4 could never become
    // ready (is_ready only satisfies a MERGED dep) and sat in Todo for 32
    // hours. The deadlock notice existed but matched only AgentStatus::Failed,
    // and a stopped run is recorded as "cancelled" — so nothing was ever said.
    let mut app = App::new();
    let mut blocker = test_agent_run("run-n1", "sampler daemon");
    blocker.node_id = Some("n1".to_string());
    blocker.status = AgentStatus::Stopped;
    app.agents.push(blocker);
    app.plans[0].planned_nodes = vec![PlannedNode {
        plan_id: String::new(),
        id: "n3".to_string(),
        title: "menu bar app".to_string(),
        prompt: "build the menu bar app".to_string(),
        goal: None,
        success: None,
        deps: vec!["n1".to_string()],
        soft_deps: vec![],
        backend: None,
        model: None,
        effort: None,
    }];
    app.plans[0].awaiting_approval = false;

    app.notice = None;
    app.run_scheduler_for(0);
    let notice = app.notice.as_deref().unwrap_or_default();
    assert!(
        notice.contains("stalled") && notice.contains("n1"),
        "a stopped dependency must name the stall: {notice:?}"
    );
}

#[test]
fn a_long_silent_running_row_says_how_long_it_has_been_quiet() {
    // The battery orchestrator sat at "running" for 32 hours with a live but
    // idle process; the row read identically to one doing real work.
    let mut run = test_agent_run("run-quiet", "orchestrating");
    run.status = AgentStatus::Running;
    run.last_output_at = Instant::now() - Duration::from_secs(3 * 3600);
    let text = agent_status_text(&run);
    assert!(text.contains("quiet"), "a silent row must say so: {text:?}");
    assert!(text.contains("3h"), "and for how long: {text:?}");

    // A freshly active agent stays clean — no nag on normal work.
    let mut busy = test_agent_run("run-busy", "orchestrating");
    busy.status = AgentStatus::Running;
    busy.last_output_at = Instant::now();
    assert!(
        !agent_status_text(&busy).contains("quiet"),
        "an active row must not be labelled quiet"
    );
}

#[test]
fn buffered_dd_bursts_cannot_cascade_across_rows() {
    // The field failure: a slow (synchronous) workspace removal froze the UI,
    // the user hammered dd, and the buffered presses replayed as arm+confirm
    // pairs against successive rows — deleting every tree on the board. A
    // confirm now only counts after a frame RENDERS post-arm (the user saw
    // the notice). With no frames between presses, any number of d presses
    // may arm but never confirm.
    let mut app = App::new();
    for i in 0..3 {
        app.agents.push(test_agent_run(&format!("run-{i}"), "task"));
    }
    app.selected_agent = 0;
    for _ in 0..8 {
        app.delete_selected_agent();
    }
    assert_eq!(
        app.agents.len(),
        3,
        "a burst with no rendered frame deletes nothing"
    );
    // The normal human cadence still works: arm, see the notice, confirm.
    app.frames_drawn += 1;
    app.delete_selected_agent(); // re-arm (the burst left it armed at this frame)
    app.frames_drawn += 1;
    app.delete_selected_agent();
    assert_eq!(
        app.agents.len(),
        2,
        "a seen confirm still deletes exactly one row"
    );
}

