#[test]
fn consumed_markers_report_their_outcome_back_to_the_orchestrator() {
    // Rudder strips each marker line as it runs it, so a failed marker vanishes
    // from RUDDER.md exactly like a successful one. Without the outcome written
    // back, the conductor cannot tell the two apart and reports a success that
    // never happened.
    let mut app = App::new();
    app.record_control_result(
        "RUDDER_INJECT n7 keep going",
        "RUDDER_INJECT target not found: n7",
    );
    app.record_control_result("RUDDER_NUDGE_ALL keep going", "nudged 3 workers");

    let rendered: Vec<(String, String)> = app
        .control_results
        .iter()
        .map(|entry| (entry.marker.clone(), entry.outcome.clone()))
        .collect();

    let mut body = String::new();
    crate::gitio::append_control_results(&mut body, &rendered);
    assert!(body.contains("RUDDER_INJECT target not found: n7"));
    assert!(body.contains("nudged 3 workers"));
    // Newest first, so the conductor reads its most recent action at the top.
    let inject_at = body.find("RUDDER_INJECT n7").expect("inject entry");
    let nudge_at = body.find("RUDDER_NUDGE_ALL").expect("nudge entry");
    assert!(
        nudge_at < inject_at,
        "newest control result is listed first"
    );
}

#[test]
fn control_results_stay_bounded_and_empty_renders_nothing() {
    let mut app = App::new();
    let mut body = String::new();
    crate::gitio::append_control_results(&mut body, &[]);
    assert!(
        body.is_empty(),
        "no section until a marker has actually run"
    );

    for index in 0..40 {
        app.record_control_result(&format!("RUDDER_MERGE n{index}"), "merged");
    }
    assert!(
        app.control_results.len() <= 12,
        "the feedback log is bounded so it never crowds out RUDDER.md"
    );
    assert_eq!(
        app.control_results.last().unwrap().marker,
        "RUDDER_MERGE n39"
    );
}

#[test]
fn a_rejected_marker_is_recorded_as_a_failure_not_silently_swallowed() {
    // End to end through the real consume path: the conductor writes a marker
    // aimed at a node that does not exist, Rudder strips the line, and the
    // rejection has to survive as a control result. Otherwise the conductor sees
    // only that its line is gone and reports the injection as done.
    let repo = unique_test_repo("orch-marker-outcome");
    fs::write(
        repo.join("RUDDER.md"),
        "notes\nRUDDER_INJECT n404 keep going\nRUDDER_NUDGE_ALL keep going\nmore notes\n",
    )
    .unwrap();

    let mut app = App::new();
    app.cwd = repo.clone();
    app.interactive_orchestrator = true;
    let mut orch = test_agent_run("orch-1", "plan it");
    orch.cwd = repo.clone();
    orch.mode = AgentMode::RudderPlan;
    orch.autosteered = false;
    orch.interactive_orchestrator = true;
    orch.status = AgentStatus::Running;
    app.agents.push(orch);

    app.scan_orchestrator_skill_markers();

    let outcomes: Vec<(&str, &str)> = app
        .control_results
        .iter()
        .map(|entry| (entry.marker.as_str(), entry.outcome.as_str()))
        .collect();
    assert_eq!(
        outcomes,
        vec![
            (
                "RUDDER_INJECT n404 keep going",
                "RUDDER_INJECT target not found: n404"
            ),
            // Only the orchestrator is present, and it is never a nudge target.
            (
                "RUDDER_NUDGE_ALL keep going",
                "no live workers to nudge"
            ),
        ],
        "both rejections survive as outcomes the conductor can read"
    );

    let text = fs::read_to_string(repo.join("RUDDER.md")).unwrap();
    assert!(
        !text.contains("RUDDER_INJECT"),
        "the marker line is still consumed"
    );
    assert!(text.contains("notes"), "surrounding prose is preserved");
}

#[test]
fn a_merge_conflict_starts_a_resolver_instead_of_parking_on_a_prompt() {
    // The field failure this exists for: five finished offstage nodes sat in
    // review for hours behind an unanswered "press y" modal, and because n6 hard-
    // depended on one of them the entire back half of the plan never launched.
    // Integration is automatic, so its failure path must be automatic too.
    //
    // HERMETIC: the resolver spawns a real PTY, so without a stubbed backend
    // this passed locally (claude installed) and failed every release run
    // ("failed to spawn command in PTY") where no claude exists.
    let _env = env_guard();
    let dir = unique_test_repo("merge-resolver-hermetic");
    let fake = dir.join("fake-claude.sh");
    write_fake_bin(&fake, "#!/bin/sh\nsleep 30\n");
    std::env::set_var("RUDDER_CLAUDE_BIN", &fake);

    let mut app = App::new();
    let mut run = test_agent_run("worker", "n2");
    run.node_id = Some("n2".to_string());
    run.status = AgentStatus::Done;
    run.merge_resolver = false;
    app.agents = vec![run];

    app.pending_jj_conflict = Some(vec![
        "DECISIONS.md".to_string(),
        "src/router/index.ts".to_string(),
    ]);
    app.handle_merge_error(
        "n2 task".to_string(),
        anyhow::anyhow!("merge produced conflicts"),
        None,
        None,
        None,
        Some("worker".to_string()),
    );

    assert!(
        app.conflict_prompt.is_none(),
        "a conflict on a real row never leaves a modal waiting for a keypress"
    );
    let notice = app.notice.clone().unwrap_or_default();
    assert!(
        notice.contains("resolver running"),
        "the resolver takes over the pane and says so: {notice}"
    );
    assert!(
        !notice.contains("press y"),
        "the y/n gate is gone for rows that can host a resolver"
    );
}

#[test]
fn a_resolver_that_conflicts_again_asks_rather_than_respawning_forever() {
    // Auto-resolution must not become an infinite loop: once the resolver itself
    // has conflicted, escalate to the human instead of starting another one.
    let mut app = App::new();
    let mut run = test_agent_run("worker", "n2");
    run.node_id = Some("n2".to_string());
    run.status = AgentStatus::Done;
    run.merge_resolver = true;
    app.agents = vec![run];

    app.pending_jj_conflict = Some(vec!["src/router/index.ts".to_string()]);
    app.handle_merge_error(
        "n2 task".to_string(),
        anyhow::anyhow!("merge produced conflicts"),
        None,
        None,
        None,
        Some("worker".to_string()),
    );

    assert!(
        app.conflict_prompt.is_some(),
        "the second conflict escalates to a prompt"
    );
    assert!(app.notice.clone().unwrap_or_default().contains("press y"));
}

#[test]
fn a_signal_death_says_which_signal_not_a_bare_number() {
    // A shell reports a signal death as 128 + signal, so a killed agent surfaced
    // as "agent process exited (exit 143)" -- which does not tell the reader that
    // the agent was KILLED rather than that its work failed. This is the single
    // most common death note people see, so it has to be diagnosable.
    let term = rudder_native::pty_terminal::describe_exit_code(143);
    assert!(term.contains("SIGTERM"), "{term}");
    assert!(
        term.contains("Rudder") || term.contains("shutdown") || term.contains("manual"),
        "names the plausible senders: {term}"
    );

    let kill = rudder_native::pty_terminal::describe_exit_code(137);
    assert!(kill.contains("SIGKILL"), "{kill}");
    assert!(
        kill.contains("out-of-memory"),
        "points at the usual cause: {kill}"
    );

    assert!(rudder_native::pty_terminal::describe_exit_code(130).contains("SIGINT"));
    // A genuine non-signal failure still reports its code plainly.
    assert_eq!(rudder_native::pty_terminal::describe_exit_code(1), "exit 1");
    assert_eq!(rudder_native::pty_terminal::describe_exit_code(2), "exit 2");
}

#[test]
fn a_specific_failure_reason_is_not_overwritten_by_the_generic_exit_symptom() {
    // Once the child is gone every later drain fails with the same generic
    // "agent process exited" line. When Rudder already recorded a real cause --
    // its own lifecycle-sweep kill, a merge failure -- that cause is the useful
    // one. Overwriting it with the symptom is why so many rows read as an
    // undiagnosable exit code.
    let mut run = test_agent_run("worker", "n0");
    run.status = AgentStatus::Failed;
    run.last_error = Some("worker lifecycle hooks were not installed".to_string());
    let already_diagnosed = run.status == AgentStatus::Failed && run.last_error.is_some();
    assert!(already_diagnosed, "the guard sees an existing diagnosis");

    let mut fresh = test_agent_run("worker-2", "n1");
    fresh.status = AgentStatus::Running;
    let fresh_diagnosed = fresh.status == AgentStatus::Failed && fresh.last_error.is_some();
    assert!(
        !fresh_diagnosed,
        "an undiagnosed row still records the exit reason"
    );
}

#[test]
fn trunk_verification_asks_jj_once_for_every_merged_row() {
    // The per-row version spawned a `jj log` for each merged row on the UI thread
    // every reconcile. jj's work is trivial next to process startup, so the cost
    // scaled with merged-row count: ~206ms for 16 rows versus ~10ms asking once.
    // In a repo with a long agent history that is a visible periodic stall.
    let repo = unique_test_repo("trunk-batch");

    // Not a jj/git repo, so the batched call answers nothing rather than
    // spawning anything -- the cheap path stays cheap.
    let answers = jj_changes_in_trunk(&repo, &["abc".to_string(), "def".to_string()]);
    assert!(answers.is_empty());

    // An empty id list must never shell out at all.
    assert!(jj_changes_in_trunk(&repo, &[]).is_empty());
    assert!(jj_changes_in_trunk(&repo, &["   ".to_string()]).is_empty());
}

fn hardening_item(title: &str, files: &[&str]) -> crate::tasks::HardeningItem {
    crate::tasks::HardeningItem {
        title: title.to_string(),
        prompt: title.to_string(),
        origin_node: "n0".to_string(),
        plan_id: "p1".to_string(),
        files: files.iter().map(|f| (*f).to_string()).collect(),
    }
}

#[test]
fn hardening_findings_on_the_same_files_become_one_clump() {
    // The offstage failure, exactly: two hardening follow-ups each independently
    // created the same four src/router files, conflicted 3-sided, and froze
    // integration for hours. As one clump they are edits in a single working copy
    // and the conflict cannot exist.
    let clusters = crate::tasks::cluster_hardening(vec![
        hardening_item(
            "--video routes to container",
            &["src/router/index.ts", "src/router/signals.ts"],
        ),
        hardening_item(
            "webdriver tools route to container",
            &["src/router/index.ts", "src/router/inspect.ts"],
        ),
        hardening_item(
            "cap retained output at 4MB",
            &["src/lanes/headless/parse.ts"],
        ),
    ]);

    assert_eq!(
        clusters.len(),
        2,
        "the two router findings clump, the lane one stands alone"
    );
    let router = clusters
        .iter()
        .find(|c| c.len() == 2)
        .expect("router clump");
    assert!(router.iter().any(|i| i.title.contains("--video")));
    assert!(router.iter().any(|i| i.title.contains("webdriver")));
}

#[test]
fn clumping_is_transitive_across_a_shared_file() {
    // A touches x, B touches x+y, C touches y. All three belong together: an agent
    // fixing y must see what A did to x, or it re-litigates the same file.
    let clusters = crate::tasks::cluster_hardening(vec![
        hardening_item("A", &["src/x.ts"]),
        hardening_item("C", &["src/y.ts"]),
        hardening_item("B", &["src/x.ts", "src/y.ts"]),
    ]);
    assert_eq!(clusters.len(), 1, "the bridging finding merges both clumps");
    assert_eq!(clusters[0].len(), 3);
}

#[test]
fn findings_with_no_identifiable_file_stay_separate() {
    // Sweeping unattributable findings into an arbitrary clump would hand one agent
    // two unrelated jobs, which is the failure mode clumping exists to avoid.
    let clusters = crate::tasks::cluster_hardening(vec![
        hardening_item("tighten the docs", &[]),
        hardening_item("review error copy", &[]),
        hardening_item("fix router", &["src/router/index.ts"]),
    ]);
    assert_eq!(clusters.len(), 3);
}

#[test]
fn file_mentions_are_recovered_from_free_text() {
    let files = crate::tasks::extract_file_mentions(
        "constraintStatus() in scripts/migrate-comeback.ts must match pg_constraint; \
         also update `tests/router.classify.test.ts` and the README.md note.",
    );
    assert!(
        files.contains(&"scripts/migrate-comeback.ts".to_string()),
        "{files:?}"
    );
    assert!(
        files.contains(&"tests/router.classify.test.ts".to_string()),
        "{files:?}"
    );
    assert!(files.contains(&"README.md".to_string()), "{files:?}");
    // Prose is not a path.
    assert!(
        !files.iter().any(|f| f == "constraintStatus()"),
        "{files:?}"
    );
}

#[test]
fn many_findings_on_one_area_become_one_node_not_many() {
    // The whole point. Four findings across two areas used to be four nodes: four
    // cold-start agents, four workspaces, four merges — and the two router findings
    // would race to create the same files. They become two nodes.
    let mut app = App::new();
    app.cwd = std::env::temp_dir();
    let mut a = test_agent_run("n0agent", "router");
    a.node_id = Some("n0".to_string());
    a.mode = AgentMode::Execute;
    app.agents = vec![a];

    let note = serde_json::json!({
        "summary": "built the router",
        "followups": [
            { "title": "video routing needs src/router/index.ts guard", "scope": "in" },
            { "title": "webdriver routing in src/router/index.ts is unhandled", "scope": "in" },
            { "title": "cap output in src/lanes/headless/parse.ts", "scope": "in" },
            { "title": "docs for src/lanes/headless/parse.ts limits", "scope": "in" }
        ]
    });
    assert!(app.apply_worker_followups("n0", &note));
    assert_eq!(app.hardening.len(), 4, "all four are captured");
    assert_eq!(
        app.plan().planned_nodes.len(),
        0,
        "and none of them is scheduled yet"
    );

    let added = app.flush_hardening_into_plan(0);
    assert_eq!(added, 2, "four findings, two file-areas, two nodes");

    let titles: Vec<&str> = app
        .plan()
        .planned_nodes
        .iter()
        .map(|n| n.title.as_str())
        .collect();
    assert!(
        titles.iter().any(|t| t.contains("src/router")),
        "a clump is named for its area: {titles:?}"
    );

    // Every finding in a clump reaches the agent in ONE prompt, so it fixes them
    // together with full sight of the file instead of two agents half-fixing it.
    let router = app
        .plan()
        .planned_nodes
        .iter()
        .find(|n| n.title.contains("src/router"))
        .expect("router clump");
    assert!(router.prompt.contains("video routing"));
    assert!(router.prompt.contains("webdriver routing"));
    assert!(router.prompt.contains("reported by n0"));
}

#[test]
fn the_backlog_survives_a_restart() {
    // A finding recorded and then lost is hardening the user was told would happen
    // and never does.
    let repo = unique_test_repo("hardening-persist");
    let mut app = App::new();
    app.cwd = repo.clone();
    app.hardening = vec![crate::tasks::HardeningItem {
        title: "cap the output".to_string(),
        prompt: "cap it".to_string(),
        origin_node: "n2".to_string(),
        plan_id: "p1".to_string(),
        files: vec!["src/lanes/headless/parse.ts".to_string()],
    }];
    app.persist_hardening();

    let reloaded = load_hardening_backlog(&repo);
    assert_eq!(reloaded, app.hardening);

    // Draining it clears the file rather than leaving a stale backlog behind.
    app.hardening.clear();
    app.persist_hardening();
    assert!(load_hardening_backlog(&repo).is_empty());
}

#[test]
fn git_state_is_recomputed_only_when_git_writes() {
    // A TTL cache re-runs its subprocess on a clock; git state in a repo nobody is
    // committing to is unchanged for hours, so that work is wasted. Stamp the files
    // git itself writes and recompute only when one moves.
    let repo = unique_test_repo("git-state-cache");
    clear_git_state_cache();

    // Not a repo: the answer is false, and asking again must not re-spawn.
    assert!(!is_git_repo(&repo));
    assert!(!is_git_repo(&repo));

    std::process::Command::new("git")
        .args(["init", "-q", "."])
        .current_dir(&repo)
        .status()
        .expect("git init");

    // The stamps moved (.git now exists), so the stale `false` must not survive.
    assert!(
        is_git_repo(&repo),
        "creating the repo invalidates the cached answer"
    );

    // And a repeat call is served from cache: same answer, no new stamps.
    assert!(is_git_repo(&repo));
    clear_git_state_cache();
}

#[test]
fn a_branch_switch_invalidates_the_cached_branch() {
    let repo = unique_test_repo("git-branch-cache");
    clear_git_state_cache();
    let git = |args: &[&str]| {
        std::process::Command::new("git")
            .args(args)
            .current_dir(&repo)
            .status()
            .expect("git");
    };
    git(&["init", "-q", "."]);
    git(&["config", "user.email", "t@example.com"]);
    git(&["config", "user.name", "T"]);
    std::fs::write(repo.join("a.txt"), "hi").unwrap();
    git(&["add", "-A"]);
    git(&["commit", "-qm", "base"]);

    let first = current_branch_at(&repo);
    assert!(first.is_some(), "a branch is reported");
    // Cached: same answer without git having moved.
    assert_eq!(current_branch_at(&repo), first);

    git(&["checkout", "-q", "-b", "feature-branch"]);
    assert_eq!(
        current_branch_at(&repo).as_deref(),
        Some("feature-branch"),
        "switching branches rewrites .git/HEAD, which invalidates the cache"
    );
    clear_git_state_cache();
}

#[test]
fn solo_hides_the_other_panes_and_toggles_back() {
    let mut app = App::new();
    assert!(!app.solo_pane, "the split is the default");

    app.focus = FocusPane::Worker;
    app.toggle_solo_pane();
    assert!(app.solo_pane);
    assert!(
        app.notice.as_deref().unwrap_or_default().contains("⌥h"),
        "the notice says how to get back: {:?}",
        app.notice
    );
    assert_eq!(app.focus, FocusPane::Worker);

    app.toggle_solo_pane();
    assert!(!app.solo_pane);
    assert_eq!(app.focus, FocusPane::Worker);

    // From the TASK pane, focus has to move: the task line is not drawn in full
    // screen, so keys typed at it would land in an input the user cannot see.
    app.focus = FocusPane::Task;
    app.toggle_solo_pane();
    assert_eq!(
        app.focus,
        FocusPane::Worker,
        "focus leaves the hidden task line"
    );
    app.toggle_solo_pane();
    assert_eq!(
        app.focus,
        FocusPane::Task,
        "and comes back when the panes do"
    );
}

#[test]
fn solo_leaves_no_stale_rect_for_the_hidden_pane() {
    // agents_area/worker_area are what mouse hit-testing and scroll routing read.
    // A rect left behind for a pane that is no longer drawn would take clicks meant
    // for the soloed pane.
    let mut app = App::new();
    app.solo_pane = true;
    app.focus = FocusPane::Worker;
    let mut terminal =
        ratatui::Terminal::new(ratatui::backend::TestBackend::new(100, 30)).expect("terminal");
    terminal
        .draw(|frame| crate::render::render(frame, &mut app))
        .expect("draw");
    assert!(app.worker_area.is_some(), "the soloed pane owns a rect");
    assert!(app.agents_area.is_none(), "the hidden pane owns none");
    // The task line is hidden too, so it must not keep a rect that would take
    // clicks over the full-screen pane now drawn where it used to be.
    assert!(app.task_area.is_none(), "the hidden task line owns none");

    app.focus = FocusPane::Agents;
    terminal
        .draw(|frame| crate::render::render(frame, &mut app))
        .expect("draw");
    assert!(app.agents_area.is_some());
    assert!(app.worker_area.is_none());
}

#[test]
fn alt_h_hides_the_panes_and_stepping_is_brackets_only() {
    // Alt+h used to be an ALIAS for the agent stepper; the real binding is
    // Alt+[ / Alt+], which is why spending the alias on hiding costs nothing.
    let mut app = App::new();
    app.agents = vec![test_agent_run("a", "first"), test_agent_run("b", "second")];
    app.focus = FocusPane::Agents;
    app.selected_agent = 1;

    app.handle_key(KeyEvent::new(KeyCode::Char('h'), KeyModifiers::ALT));
    assert!(app.solo_pane, "Alt+h hides the other panes");
    assert_eq!(app.selected_agent, 1, "and does not move the selection");

    app.handle_key(KeyEvent::new(KeyCode::Char('h'), KeyModifiers::ALT));
    assert!(!app.solo_pane, "Alt+h again restores the split");

    // Stepping is Alt+[ / Alt+] only — the letter aliases are gone.
    app.handle_key(KeyEvent::new(KeyCode::Char('['), KeyModifiers::ALT));
    assert_eq!(app.selected_agent, 0, "Alt+[ steps back");
    app.handle_key(KeyEvent::new(KeyCode::Char(']'), KeyModifiers::ALT));
    assert_eq!(app.selected_agent, 1, "Alt+] steps forward");
    assert!(!app.solo_pane, "stepping never toggles the hide");

    // Alt+l no longer steps: it is free again.
    app.handle_key(KeyEvent::new(KeyCode::Char('l'), KeyModifiers::ALT));
    assert_eq!(app.selected_agent, 1, "Alt+l is no longer a stepper alias");
}

#[test]
fn a_diff_summary_miss_never_blocks_the_frame() {
    // `sample` of a live session found 984 of 1030 render frames parked in
    // Command::output waiting for jj to answer this. Render runs on the main
    // thread and every keystroke draws a frame, so that wait IS the typing lag.
    // A miss must hand back whatever we have and compute off-thread.
    let repo = unique_test_repo("diff-summary-async");
    let mut app = App::new();
    app.cwd = repo.clone();

    let started = std::time::Instant::now();
    let first = app.cached_diff_summary("row-1", &repo, true);
    let elapsed = started.elapsed();
    assert!(first.is_none(), "nothing cached yet, so nothing to show");
    assert!(
        elapsed < Duration::from_millis(50),
        "the miss returned immediately instead of waiting on a subprocess: {elapsed:?}"
    );
    assert!(
        app.diff_summary_inflight.contains("row-1"),
        "the real work was handed to a background thread"
    );

    // A second ask while it is still running must NOT spawn another subprocess.
    let _ = app.cached_diff_summary("row-1", &repo, true);
    assert_eq!(
        app.diff_summary_inflight.len(),
        1,
        "one row, one computation"
    );

    // Once the answer lands, draining installs it and marks the screen dirty.
    for _ in 0..200 {
        app.drain_diff_summaries();
        if !app.diff_summary_inflight.contains("row-1") {
            break;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    assert!(
        !app.diff_summary_inflight.contains("row-1"),
        "the background result was absorbed"
    );
    assert!(app.diff_summary_cache.contains_key("row-1"));
}

#[test]
fn a_settled_row_is_answered_from_cache_without_recomputing() {
    // A merged/failed row's diff is final. Re-asking spends two subprocesses for an
    // answer that cannot have changed.
    let repo = unique_test_repo("diff-summary-settled");
    let mut app = App::new();
    app.cwd = repo.clone();
    app.diff_summary_cache.insert(
        "settled".to_string(),
        (
            Instant::now() - Duration::from_secs(3600),
            Some("+3 -1".to_string()),
        ),
    );

    let value = app.cached_diff_summary("settled", &repo, false);
    assert_eq!(
        value.as_deref(),
        Some("+3 -1"),
        "an hour-old answer still serves"
    );
    assert!(
        app.diff_summary_inflight.is_empty(),
        "and nothing was recomputed for it"
    );
}

#[test]
fn the_tab_glyph_distinguishes_states_by_shape_not_colour() {
    // A tab strip is read at a glance and at ~14px. The old set was four coloured
    // circles, so a running session looked identical to a finished one until you
    // focused on the hue. These differ in SHAPE.
    let mut app = App::new();

    // Nothing at all: an empty circle.
    assert_eq!(app.tab_status_glyph(), '○');

    let mut running = test_agent_run("r", "work");
    running.status = AgentStatus::Running;
    app.agents = vec![running];
    assert!(
        App::TAB_SPINNER.contains(&app.tab_status_glyph()),
        "running turns"
    );

    // Every agent finished: a full circle.
    app.agents[0].status = AgentStatus::Merged;
    assert_eq!(app.tab_status_glyph(), '●');
    app.agents[0].status = AgentStatus::Done;
    assert_eq!(app.tab_status_glyph(), '●');

    // A failure is neither circle nor square — while it is news. A live failure
    // marks the tab until you touch the dashboard again; one loaded from disk
    // (no completion instant: it died in an earlier session) is history and
    // must not pin ⊗ on a tab where nothing is happening.
    app.agents[0].status = AgentStatus::Failed;
    app.agents[0].completed_at = Some(Instant::now());
    assert_eq!(app.tab_status_glyph(), '⊗');
    app.note_user_activity();
    assert_ne!(
        app.tab_status_glyph(),
        '⊗',
        "a keypress after the failure means you have seen it"
    );
    app.agents[0].completed_at = None;
    assert_ne!(
        app.tab_status_glyph(),
        '⊗',
        "a failure from an earlier session is history, not news"
    );
    app.agents[0].completed_at = Some(Instant::now());
    assert_eq!(app.tab_status_glyph(), '⊗', "a new failure is news again");

    // Waiting on YOU outranks everything: it is the one state that will not
    // resolve without you, so it must win over a sibling that is still running.
    app.agents[0].status = AgentStatus::Running;
    let mut waiting = test_agent_run("w", "asking");
    waiting.status = AgentStatus::Running;
    waiting.needs_user_input = true;
    app.agents.push(waiting);
    assert_eq!(app.tab_status_glyph(), '⬓', "square, bottom half filled");
}

#[test]
fn the_tab_spinner_turns_on_a_clock_not_on_frames() {
    // The draw loop runs at ~30fps. A glyph advancing per frame reads as flicker
    // in the corner of the eye rather than as progress.
    let mut app = App::new();
    let mut running = test_agent_run("r", "work");
    running.status = AgentStatus::Running;
    app.agents = vec![running];

    let first = app.tab_status_glyph();
    // Several draws inside one interval must not move it.
    for _ in 0..20 {
        assert_eq!(app.tab_status_glyph(), first, "steady within the interval");
    }

    // Once the interval passes, it advances exactly one step.
    app.tab_spinner_at = Instant::now() - TAB_SPINNER_INTERVAL - Duration::from_millis(10);
    let second = app.tab_status_glyph();
    assert_ne!(second, first, "and turns once the interval elapses");
    assert!(App::TAB_SPINNER.contains(&second));
}

