/// A live worker whose turn ends on an API error reports it, the tab shows a
/// failure, and the next prompt clears it — without the run ever being Failed.
#[cfg(not(windows))]
#[test]
fn an_api_error_turn_end_is_shown_as_a_failure_until_the_next_prompt() {
    let _env = env_guard();
    let run_id = "sig-error-itest";
    let Some(sig) = crate::signals::signal_path(run_id) else {
        return;
    };
    let _ = std::fs::remove_file(&sig);
    crate::signals::prepare_worker_signals(run_id, Backend::Claude);

    let mut app = App::new();
    app.cwd = std::env::temp_dir();
    let pane = TerminalPane::spawn_shell_or_command(
        Some(TerminalCommand::with_args("/bin/sh", ["-lc", "sleep 30"])),
        TerminalPaneOptions {
            size: TerminalSize { rows: 10, cols: 80 },
            scrollback_lines: 100,
            ..Default::default()
        },
    )
    .expect("spawn worker pty");
    let mut run = test_agent_run(run_id, "do the thing");
    run.cwd = app.cwd.clone();
    run.backend = Backend::Claude;
    run.terminal = Some(pane);
    app.agents.push(run);
    app.selected_agent = 0;
    if let Some(parent) = sig.parent() {
        std::fs::create_dir_all(parent).expect("signals dir");
    }

    std::fs::write(&sig, "{\"state\":\"error\",\"detail\":\"rate_limit\"}").expect("write signal");
    app.poll_agents();
    assert_eq!(
        app.agents[0].status,
        AgentStatus::Running,
        "process is alive; not Failed"
    );
    assert_eq!(app.agents[0].turn_error(), Some("rate_limit"));
    assert!(!sig.exists(), "consumed one-shot");
    assert_eq!(
        crate::render::agent_status_label(&app.agents[0]),
        "turn failed · retry"
    );
    assert_eq!(
        app.tab_status_glyph(),
        '⊗',
        "the tab says something needs you"
    );
    app.poll_agents();
    assert_eq!(
        app.agents[0].turn_error(),
        Some("rate_limit"),
        "latched: the error is still what it waits on"
    );

    // The human sends a new prompt: back to work.
    std::fs::write(&sig, "{\"state\":\"working\"}").expect("write signal");
    app.poll_agents();
    assert_eq!(app.agents[0].turn_error(), None);
    assert!(
        App::TAB_SPINNER.contains(&app.tab_status_glyph()),
        "running again"
    );

    // An error with no detail still shows as an error.
    std::fs::write(&sig, "{\"state\":\"error\"}").expect("write signal");
    app.poll_agents();
    assert_eq!(app.agents[0].turn_error(), Some("api error"));
    signals::cleanup_run_signals(run_id);
}

#[test]
fn native_notification_commands_pass_text_as_argv_never_as_script() {
    use crate::notify::{native_notification_command, DesktopNote, NativeNotifier};
    let hostile = "fix \"auth\"; rm -rf / && say 'hi'";
    let note = DesktopNote {
        repo: "repo".to_string(),
        event: "✔ ready for review".to_string(),
        task: hostile.to_string(),
    };

    let (program, args) = native_notification_command(
        &NativeNotifier::TerminalNotifier(PathBuf::from(
            "/x/Rudder.app/Contents/MacOS/terminal-notifier",
        )),
        &note,
        Some("com.mitchellh.ghostty"),
    );
    assert_eq!(
        program,
        PathBuf::from("/x/Rudder.app/Contents/MacOS/terminal-notifier")
    );
    assert_eq!(
        args[0..4],
        ["-title", "repo", "-message", hostile],
        "repo on top, task as the message; the bundle carries the Rudder name"
    );
    assert!(
        args.windows(2)
            .any(|w| w[0] == "-subtitle" && w[1] == "✔ ready for review"),
        "the event is the subtitle line: {args:?}"
    );
    assert!(
        args.windows(2)
            .any(|w| w[0] == "-activate" && w[1] == "com.mitchellh.ghostty"),
        "clicking the notification brings the terminal forward: {args:?}"
    );

    // No task: the event is the message, and there is no empty subtitle.
    let bare = DesktopNote {
        repo: "repo".to_string(),
        event: "needs permission".to_string(),
        task: String::new(),
    };
    let (_, args) = native_notification_command(
        &NativeNotifier::TerminalNotifier(PathBuf::from("tn")),
        &bare,
        None,
    );
    assert_eq!(
        args[0..4],
        ["-title", "repo", "-message", "needs permission"]
    );
    assert!(!args.iter().any(|a| a == "-subtitle"), "{args:?}");
    assert!(
        !args.iter().any(|a| a == "-activate"),
        "no bundle, no flag: {args:?}"
    );

    let (program, args) = native_notification_command(
        &NativeNotifier::Osascript(PathBuf::from("/usr/bin/osascript")),
        &note,
        None,
    );
    assert_eq!(program, PathBuf::from("/usr/bin/osascript"));
    let script = args
        .iter()
        .filter(|a| !a.starts_with('-'))
        .take(3)
        .cloned()
        .collect::<Vec<_>>();
    assert!(
        script.iter().all(|line| !line.contains(hostile)),
        "text must reach AppleScript through argv, not by interpolation: {args:?}"
    );
    assert_eq!(
        args[args.len() - 2..],
        [
            "Rudder · repo".to_string(),
            format!("✔ ready for review — {hostile}")
        ]
    );

    let (_, args) = native_notification_command(
        &NativeNotifier::NotifySend(PathBuf::from("/usr/bin/notify-send")),
        &bare,
        None,
    );
    assert_eq!(args, ["-a", "Rudder", "Rudder · repo", "needs permission"]);

    // Control characters are scrubbed on every channel, same as the OSC path.
    let dirty = DesktopNote {
        repo: "a\x1b]b".to_string(),
        event: "c\x07d".to_string(),
        task: String::new(),
    };
    let (_, args) = native_notification_command(
        &NativeNotifier::NotifySend(PathBuf::from("n")),
        &dirty,
        None,
    );
    assert_eq!(args[2..], ["Rudder · a ]b", "c d"]);
}

#[test]
fn terminal_notifier_bundle_is_found_behind_a_wrapper_or_a_symlink() {
    use crate::notify::terminal_notifier_app_from;
    let _env = env_guard();
    let dir = std::env::temp_dir().join(format!("rudder-tn-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let app = dir.join("Cellar/terminal-notifier.app");
    let exe_dir = app.join("Contents/MacOS");
    std::fs::create_dir_all(&exe_dir).expect("bundle dirs");
    std::fs::write(exe_dir.join("terminal-notifier"), "").expect("exe");
    std::fs::create_dir_all(dir.join("bin")).expect("bin");

    // Homebrew's bash wrapper.
    let wrapper = dir.join("bin/terminal-notifier");
    std::fs::write(
        &wrapper,
        format!(
            "#!/bin/bash\nexec \"{}/Contents/MacOS/terminal-notifier\" \"$@\"\n",
            app.display()
        ),
    )
    .expect("wrapper");
    let found = terminal_notifier_app_from(&wrapper).expect("wrapper resolves");
    assert_eq!(
        std::fs::canonicalize(found).ok(),
        std::fs::canonicalize(&app).ok()
    );

    // A direct path into the bundle.
    let found = terminal_notifier_app_from(&exe_dir.join("terminal-notifier")).expect("inside");
    assert_eq!(
        std::fs::canonicalize(found).ok(),
        std::fs::canonicalize(&app).ok()
    );

    // Something unrelated: nothing, never a guess.
    std::fs::write(dir.join("bin/other"), "#!/bin/sh\necho hi\n").expect("other");
    assert_eq!(terminal_notifier_app_from(&dir.join("bin/other")), None);
    let _ = std::fs::remove_dir_all(&dir);
}

/// Against the REAL homebrew bundle when present: the copy must be renamed,
/// re-iconed and validly signed, and a second call must be a no-op.
#[cfg(target_os = "macos")]
#[test]
fn rudder_notifier_app_is_a_renamed_signed_copy_of_terminal_notifier() {
    use crate::notify::{ensure_rudder_notifier_app, terminal_notifier_app_from};
    let _env = env_guard();
    let Some(source) = crate::notify::detect_native_notifier().and_then(|n| match n {
        crate::notify::NativeNotifier::TerminalNotifier(_) => {
            let path = std::env::var_os("PATH")?;
            std::env::split_paths(&path)
                .map(|d| d.join("terminal-notifier"))
                .find(|c| c.is_file())
                .and_then(|bin| terminal_notifier_app_from(&bin))
        }
        _ => None,
    }) else {
        return; // no terminal-notifier here
    };
    let home = std::env::temp_dir().join(format!("rudder-home-tn-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&home);

    let exe = ensure_rudder_notifier_app(&source, &home).expect("bundle built");
    assert!(exe.is_file(), "{}", exe.display());
    let app = home.join("notifier/Rudder.app");
    let plist = |key: &str| -> String {
        let out = std::process::Command::new("plutil")
            .args(["-extract", key, "raw", "-o", "-"])
            .arg(app.join("Contents/Info.plist"))
            .output()
            .expect("plutil");
        String::from_utf8_lossy(&out.stdout).trim().to_string()
    };
    assert_eq!(plist("CFBundleIdentifier"), "dev.viraat.rudder.notifier");
    assert_eq!(plist("CFBundleName"), "Rudder");
    assert_eq!(plist("CFBundleIconFile"), "Rudder");
    assert!(
        app.join("Contents/Resources/Rudder.icns").is_file(),
        "icon shipped"
    );
    assert!(
        !app.join("Contents/Resources/Terminal.icns").exists(),
        "Terminal's icon gone"
    );
    let verified = std::process::Command::new("codesign")
        .args(["--verify", "--deep"])
        .arg(&app)
        .status()
        .expect("codesign")
        .success();
    assert!(
        verified,
        "ad-hoc signature must validate or macOS drops the notification"
    );

    // Second call: cached, same executable, no rebuild (stamp unchanged).
    let stamp = home.join("notifier/Rudder.app.stamp");
    assert!(
        stamp.is_file(),
        "stamp is beside the bundle, never inside the seal"
    );
    let before = std::fs::metadata(&stamp)
        .and_then(|m| m.modified())
        .expect("stamp");
    let again = ensure_rudder_notifier_app(&source, &home).expect("cached");
    assert_eq!(again, exe);
    let after = std::fs::metadata(&stamp)
        .and_then(|m| m.modified())
        .expect("stamp");
    assert_eq!(before, after, "no rebuild when nothing changed");
    let _ = std::fs::remove_dir_all(&home);
}

#[test]
fn native_notifier_detection_prefers_terminal_notifier_then_osascript() {
    use crate::notify::{detect_native_notifier, NativeNotifier};
    let _env = env_guard();
    let dir = std::env::temp_dir().join(format!("rudder-notifier-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("dir");
    let saved = std::env::var_os("PATH");
    std::env::set_var("PATH", &dir);
    assert_eq!(
        detect_native_notifier(),
        None,
        "empty PATH: OSC 777 fallback"
    );

    if cfg!(target_os = "macos") {
        std::fs::write(dir.join("osascript"), "").expect("fake osascript");
        assert_eq!(
            detect_native_notifier(),
            Some(NativeNotifier::Osascript(dir.join("osascript")))
        );
        std::fs::write(dir.join("terminal-notifier"), "").expect("fake tn");
        assert_eq!(
            detect_native_notifier(),
            Some(NativeNotifier::TerminalNotifier(
                dir.join("terminal-notifier")
            )),
            "terminal-notifier wins: it can activate the terminal on click"
        );
    } else {
        std::fs::write(dir.join("notify-send"), "").expect("fake notify-send");
        assert_eq!(
            detect_native_notifier(),
            Some(NativeNotifier::NotifySend(dir.join("notify-send")))
        );
    }
    match saved {
        Some(path) => std::env::set_var("PATH", path),
        None => std::env::remove_var("PATH"),
    }
    let _ = std::fs::remove_dir_all(&dir);
}

/// Spawn a short-lived PTY standing in for a worker that dies AFTER its turn
/// ended: the run is already Done and idle when the process goes away.
#[cfg(not(windows))]
fn done_run_with_dying_worker(id: &str, cwd: &std::path::Path, seconds: &str) -> AgentRun {
    let pane = TerminalPane::spawn_shell_or_command(
        Some(TerminalCommand::with_args(
            "/bin/sh",
            ["-c", &format!("sleep {seconds}")],
        )),
        TerminalPaneOptions {
            size: TerminalSize { rows: 10, cols: 80 },
            scrollback_lines: 100,
            ..Default::default()
        },
    )
    .expect("spawn worker pty");
    let mut run = test_agent_run(id, "do the thing");
    run.cwd = cwd.to_path_buf();
    run.backend = Backend::Claude;
    run.status = AgentStatus::Done;
    run.completed_at = Some(Instant::now());
    run.terminal = Some(pane);
    run
}

#[cfg(not(windows))]
fn poll_until(app: &mut App, index: usize, done: impl Fn(&AgentRun) -> bool) {
    let deadline = Instant::now() + Duration::from_secs(8);
    while Instant::now() < deadline {
        app.poll_agents();
        if done(&app.agents[index]) {
            return;
        }
        std::thread::sleep(Duration::from_millis(50));
    }
    panic!(
        "condition not reached: {:?} {:?}",
        app.agents[index].status, app.agents[index].last_error
    );
}

/// The manas case: a worker answered, the row went to review, and fifteen
/// minutes later the process was gone. The row kept a live-looking pane, and
/// the next keystroke died in a dead PTY. The row must stay Done (the work
/// landed; it is still reviewable) but lose the pane and say why.
#[cfg(not(windows))]
#[test]
fn a_worker_that_dies_after_its_turn_ended_loses_its_pane_but_stays_done() {
    let _env = env_guard();
    let mut app = App::new();
    app.cwd = std::env::temp_dir();
    let run = done_run_with_dying_worker("gone-after-done-focused", &app.cwd, "0.2");
    app.agents.push(run);
    app.selected_agent = 0;

    // While the process lives, Done stays Done (no false orphaning).
    app.poll_agents();
    assert_eq!(app.agents[0].status, AgentStatus::Done);
    assert!(app.agents[0].terminal.is_some());

    poll_until(&mut app, 0, |run| run.terminal.is_none());
    let run = &app.agents[0];
    assert_eq!(
        run.status,
        AgentStatus::Done,
        "the work is intact: still reviewable and mergeable, never a new failure"
    );
    assert!(run.last_error.is_none(), "not painted as a failed run");
    let note = run.worker_exit_note.as_deref().unwrap_or_default();
    assert!(
        note.contains("exited after finishing") && note.contains("resume"),
        "says what happened and what to do: {note}"
    );
    assert!(!run.needs_user_input && !run.needs_permission && run.wait_signal.is_none());
}

/// Same death on an UNFOCUSED row, which takes the throttled fast path that
/// only ever polled liveness while Running.
#[cfg(not(windows))]
#[test]
fn an_unfocused_done_row_notices_its_worker_dying_too() {
    let _env = env_guard();
    let mut app = App::new();
    app.cwd = std::env::temp_dir();
    let dying = done_run_with_dying_worker("gone-after-done-unfocused", &app.cwd, "0.2");
    let mut focused = test_agent_run("still-here", "other work");
    focused.cwd = app.cwd.clone();
    app.agents.push(dying);
    app.agents.push(focused);
    app.selected_agent = 1;
    // Freshly drained, so the next ticks skip the drain and hit the fast path.
    app.agents[0].last_drain_at = Some(Instant::now());

    poll_until(&mut app, 0, |run| run.terminal.is_none());
    assert_eq!(app.agents[0].status, AgentStatus::Done);
    assert!(app.agents[0].worker_exit_note.is_some());
    assert_eq!(
        app.agents[1].status,
        AgentStatus::Running,
        "the live row is untouched"
    );
}

// ---- ⌥d diff panel ----

const SAMPLE_DIFF: &str = "\
diff --git a/src/lib.rs b/src/lib.rs
index 1111111..2222222 100644
--- a/src/lib.rs
+++ b/src/lib.rs
@@ -1,4 +1,5 @@ fn main() {
 use std::io;
-fn old() {}
+fn new_one() {}
+fn new_two() {}
 fn keep() {}
 fn tail() {}
\\ No newline at end of file
diff --git a/README.md b/README.md
new file mode 100644
--- /dev/null
+++ b/README.md
@@ -0,0 +1,2 @@
+# hello
+world
diff --git a/gone.txt b/gone.txt
deleted file mode 100644
--- a/gone.txt
+++ /dev/null
@@ -1 +0,0 @@
-bye
diff --git a/a.txt b/b.txt
similarity index 100%
rename from a.txt
rename to b.txt
diff --git a/logo.png b/logo.png
new file mode 100644
Binary files /dev/null and b/logo.png differ
";

#[test]
fn unified_diff_parses_files_hunks_line_numbers_and_counts() {
    use crate::diffview::{parse_unified_diff, FileKind, LineKind};
    let files = parse_unified_diff(SAMPLE_DIFF);
    assert_eq!(files.len(), 5, "{files:#?}");

    let lib = &files[0];
    assert_eq!(lib.path, "src/lib.rs");
    assert_eq!(lib.kind, FileKind::Modified);
    assert_eq!((lib.additions, lib.deletions), (2, 1));
    assert_eq!(lib.hunks.len(), 1);
    assert_eq!(lib.hunks[0].header, "@@ -1,4 +1,5 @@ fn main() {");
    let kinds: Vec<(LineKind, Option<u32>, Option<u32>)> = lib.hunks[0]
        .lines
        .iter()
        .map(|l| (l.kind, l.old_no, l.new_no))
        .collect();
    assert_eq!(
        kinds,
        vec![
            (LineKind::Context, Some(1), Some(1)),
            (LineKind::Del, Some(2), None),
            (LineKind::Add, None, Some(2)),
            (LineKind::Add, None, Some(3)),
            (LineKind::Context, Some(3), Some(4)),
            (LineKind::Context, Some(4), Some(5)),
            (LineKind::Meta, None, None),
        ],
        "line numbers advance per side"
    );

    assert_eq!(files[1].kind, FileKind::Added);
    assert_eq!(files[1].additions, 2);
    assert_eq!(files[2].kind, FileKind::Deleted);
    assert_eq!(files[2].deletions, 1);
    assert_eq!(files[3].kind, FileKind::Renamed);
    assert_eq!(files[3].old_path.as_deref(), Some("a.txt"));
    assert_eq!(files[3].path, "b.txt");
    assert!(files[3].hunks.is_empty());
    assert!(files[4].binary);
    assert_eq!(files[4].kind, FileKind::Added);
}

#[test]
fn a_jj_style_diff_without_mode_lines_still_classifies_adds_and_deletes() {
    use crate::diffview::{parse_unified_diff, FileKind};
    let text = "diff --git a/n.txt b/n.txt\n--- /dev/null\n+++ b/n.txt\n@@ -0,0 +1 @@\n+new\ndiff --git a/g.txt b/g.txt\n--- a/g.txt\n+++ /dev/null\n@@ -1 +0,0 @@\n-old\n";
    let files = parse_unified_diff(text);
    assert_eq!(files[0].kind, FileKind::Added);
    assert_eq!(files[1].kind, FileKind::Deleted);
    assert_eq!(parse_unified_diff("").len(), 0);
    assert_eq!(
        parse_unified_diff("garbage\n+not a diff\n").len(),
        0,
        "stray lines never fabricate a file"
    );
}

fn diff_panel_text(panel: &crate::diffview::DiffPanel, run: &AgentRun, width: u16) -> Vec<String> {
    crate::diffview::diff_panel_lines(panel, run, width, true)
        .0
        .iter()
        .map(flatten_line)
        .collect()
}

#[test]
fn the_diff_panel_header_carries_stats_tokens_and_an_api_rate_cost() {
    use crate::diffview::{DiffPanel, DiffSource};
    let mut run = test_agent_run("diff-1", "tighten the parser");
    run.model = "claude-opus-5".to_string();
    run.tokens_in = 2_000_000;
    run.tokens_out = 100_000;
    let mut panel = DiffPanel::new();
    panel.open = true;
    panel.track("diff-1");

    let before = diff_panel_text(&panel, &run, 100);
    assert!(
        before.iter().any(|l| l.contains("computing diff")),
        "{before:?}"
    );

    panel.apply(
        "other-run",
        Ok((SAMPLE_DIFF.to_string(), DiffSource::Jj, false)),
    );
    assert!(!panel.loaded, "a result for another run is ignored");
    panel.apply(
        "diff-1",
        Ok((SAMPLE_DIFF.to_string(), DiffSource::Jj, false)),
    );
    let text = diff_panel_text(&panel, &run, 100);
    let joined = text.join("\n");
    assert!(text[0].contains("tighten the parser"));
    assert!(joined.contains("+4 −2"), "totals across files: {joined}");
    assert!(joined.contains("5 files"));
    // 2M opus input at $15/M + 100k output at $75/M = $30 + $7.50.
    assert!(joined.contains("≈ $37.50 at API rates"), "{joined}");
    assert!(joined.contains("tokens in 2.00M · out 100.0k"), "{joined}");
    assert!(
        joined.contains(" M src/lib.rs") && joined.contains("+2 −1"),
        "file summary: {joined}"
    );
    assert!(joined.contains(" A README.md") && joined.contains(" D gone.txt"));
    assert!(
        joined.contains("a.txt → b.txt"),
        "rename shows both names: {joined}"
    );
    assert!(joined.contains("binary"), "{joined}");
    assert!(
        joined.contains("@@ -1,4 +1,5 @@"),
        "hunk headers survive: {joined}"
    );
    assert!(
        joined.contains("│+fn new_one() {}"),
        "additions carry a gutter and sigil: {joined}"
    );
    assert!(
        joined.contains("  2     │−fn old() {}"),
        "deletions show the old line number: {joined}"
    );
    assert!(joined.contains("No newline at end of file"));

    // Unpriced model: tokens still show, cost is honest about being unknown.
    run.model = "mystery-9".to_string();
    panel.revision += 1;
    let joined = diff_panel_text(&panel, &run, 100).join("\n");
    assert!(joined.contains("cost n/a"), "{joined}");

    // Errors and empties are states, not blank screens.
    panel.apply("diff-1", Err("workspace is gone".to_string()));
    let joined = diff_panel_text(&panel, &run, 100).join("\n");
    assert!(joined.contains("diff unavailable") && joined.contains("workspace is gone"));
    panel.apply("diff-1", Ok((String::new(), DiffSource::Git, false)));
    let joined = diff_panel_text(&panel, &run, 100).join("\n");
    assert!(
        joined.contains("no changes yet") && joined.contains("git vs HEAD"),
        "{joined}"
    );
    panel.apply(
        "diff-1",
        Ok((SAMPLE_DIFF.to_string(), DiffSource::Git, true)),
    );
    assert!(diff_panel_text(&panel, &run, 100)
        .join("\n")
        .contains("diff truncated"));
}

#[test]
fn diff_panel_scrolling_clamps_and_jumps_between_files() {
    use crate::diffview::{DiffPanel, DiffSource};
    let run = test_agent_run("diff-2", "scroll me");
    let mut panel = DiffPanel::new();
    panel.open = true;
    panel.track("diff-2");
    panel.apply(
        "diff-2",
        Ok((SAMPLE_DIFF.to_string(), DiffSource::Jj, false)),
    );
    let (lines, starts) = {
        let (l, s) = panel.lines(&run, 80, true);
        (l.len(), s.to_vec())
    };
    assert_eq!(starts.len(), 5, "one anchor per file");
    let viewport = 6;
    assert!(
        panel.jump_file(true, viewport),
        "n moves to the first file header"
    );
    assert_eq!(panel.scroll, starts[0]);
    assert!(panel.jump_file(true, viewport));
    assert_eq!(panel.scroll, starts[1]);
    assert!(panel.jump_file(false, viewport));
    assert_eq!(panel.scroll, starts[0]);
    assert!(panel.scroll_by(1000, viewport));
    assert_eq!(panel.scroll, lines - viewport, "never past the end");
    assert!(!panel.jump_file(true, viewport), "no file below the end");
    assert!(panel.scroll_by(-1000, viewport));
    assert_eq!(panel.scroll, 0);
    assert!(!panel.scroll_by(-1, viewport), "already at the top");

    // A new run resets the view; a fresh identical apply keeps the revision.
    let rev = panel.revision;
    panel.apply(
        "diff-2",
        Ok((SAMPLE_DIFF.to_string(), DiffSource::Jj, false)),
    );
    assert_eq!(
        panel.revision, rev,
        "unchanged content does not invalidate the cache"
    );
    panel.track("diff-3");
    assert_eq!(panel.scroll, 0);
    assert!(panel.files.is_empty() && !panel.loaded);
}

fn alt(c: char) -> KeyEvent {
    KeyEvent::new(KeyCode::Char(c), KeyModifiers::ALT)
}

#[test]
fn alt_d_opens_the_diff_panel_beside_the_worker_and_esc_closes_it() {
    let mut app = App::new();
    app.cwd = std::env::temp_dir();
    let mut run = test_agent_run("diff-app", "tighten the parser");
    run.cwd = app.cwd.clone();
    app.agents.push(run);
    app.selected_agent = 0;
    app.focus = FocusPane::Worker;

    let before = render_screen(&mut app, 160, 30);
    assert!(!before.contains("┌ diff"), "closed by default:\n{before}");

    app.handle_key(alt('d'));
    assert!(app.diff_panel.open);
    assert_eq!(app.focus, FocusPane::Diff, "opening focuses the panel");
    assert_eq!(app.diff_panel.run_id.as_deref(), Some("diff-app"));
    let open = render_screen(&mut app, 160, 30);
    assert!(
        open.contains("┌ diff"),
        "the panel has its own titled pane:\n{open}"
    );
    assert!(
        app.worker_area.is_some() && app.diff_area.is_some(),
        "side by side at 160 columns"
    );
    assert!(open.contains("computing diff"), "{open}");
    let worker_right = app.worker_area.unwrap().right();
    let diff_left = app.diff_area.unwrap().x;
    assert!(
        diff_left > worker_right,
        "diff sits to the right of the worker"
    );

    // Narrow screen: the panel takes the worker's place rather than squeezing both.
    let narrow = render_screen(&mut app, 100, 30);
    assert!(narrow.contains("┌ diff"));
    assert!(app.worker_area.is_none() && app.diff_area.is_some());

    // Keys while focused: scroll, then Esc closes and hands focus back.
    app.diff_panel.apply(
        "diff-app",
        Ok((
            SAMPLE_DIFF.to_string(),
            crate::diffview::DiffSource::Jj,
            false,
        )),
    );
    let _ = render_screen(&mut app, 160, 30);
    app.handle_key(KeyEvent::new(KeyCode::Char('n'), KeyModifiers::NONE));
    assert!(app.diff_panel.scroll > 0, "n jumped to the first file");
    let shown = render_screen(&mut app, 160, 30);
    assert!(shown.contains("src/lib.rs"), "{shown}");
    app.handle_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));
    assert!(!app.diff_panel.open);
    assert_eq!(app.focus, FocusPane::Worker);
    let closed = render_screen(&mut app, 160, 30);
    assert!(!closed.contains("┌ diff"), "{closed}");

    // The typographic fallback (Option+d without an Alt modifier) and /diff work too.
    app.handle_key(KeyEvent::new(KeyCode::Char('\u{2202}'), KeyModifiers::NONE));
    assert!(app.diff_panel.open);
    app.handle_key(alt('d'));
    assert!(!app.diff_panel.open);
    assert!(app.handle_command("/diff"));
    assert!(app.diff_panel.open);
}

#[test]
fn soloing_with_the_diff_panel_focused_shows_only_the_diff_and_alt_h_restores() {
    let mut app = App::new();
    app.cwd = std::env::temp_dir();
    let mut run = test_agent_run("diff-solo", "tighten the parser");
    run.cwd = app.cwd.clone();
    app.agents.push(run);
    app.selected_agent = 0;
    app.focus = FocusPane::Worker;
    app.handle_key(alt('d'));
    app.diff_panel.apply(
        "diff-solo",
        Ok((
            SAMPLE_DIFF.to_string(),
            crate::diffview::DiffSource::Jj,
            false,
        )),
    );

    app.handle_key(alt('h'));
    assert!(app.solo_pane);
    let solo = render_screen(&mut app, 160, 30);
    assert!(solo.contains("┌ diff"), "{solo}");
    assert!(app.agents_area.is_none() && app.worker_area.is_none());
    assert_eq!(app.diff_area.map(|a| a.width), Some(160), "full width");

    app.handle_key(alt('h'));
    assert!(!app.solo_pane);
    let back = render_screen(&mut app, 160, 30);
    assert!(
        back.contains("┌ diff"),
        "panel comes back with the split: {back}"
    );
    assert!(app.agents_area.is_some() && app.worker_area.is_some() && app.diff_area.is_some());
}

