/// The event sequence recorded from a real codex 0.162 session whose turn spawned
/// a subagent. `notify` fired three times (the hidden title thread ~4s in, the
/// subagent, and the conversation itself) and each used to mark the run done and
/// ring "ready for review". Only the conversation's own end counts.
#[cfg(not(windows))]
#[test]
fn codex_done_comes_only_from_the_conversation_thread() {
    use crate::signals::{parse_signal_state, SignalState};
    let dir = std::env::temp_dir().join(format!("rudder-codex-thread-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("dir");
    let signal = dir.join("run.json");
    let script_path = dir.join("notify.sh");
    std::fs::write(&script_path, crate::signals::codex_notify_script(&signal)).expect("script");
    let script = script_path.display().to_string();
    let hook = |payload: &str| run_hook_command(&format!("sh '{script}'"), payload);
    let notify = |thread: &str, input: &str| {
        run_hook_command(
            &format!(
                "sh '{script}' '{{\"type\":\"agent-turn-complete\",\"thread-id\":\"{thread}\",\"turn-id\":\"t\",\"input-messages\":[\"{input}\"]}}'"
            ),
            "",
        )
    };
    let take = || -> Option<SignalState> {
        let body = std::fs::read_to_string(&signal).ok()?;
        let _ = std::fs::remove_file(&signal);
        parse_signal_state(&body)
    };

    let main = "01a13c5a-917d-7503-94c7-8277680eb4ff";
    hook(&format!(r#"{{"session_id":"{main}","hook_event_name":"SessionStart","source":"startup"}}"#));
    assert_eq!(take(), None, "SessionStart only records the conversation id");
    hook(&format!(r#"{{"session_id":"{main}","turn_id":"a","hook_event_name":"UserPromptSubmit"}}"#));
    assert_eq!(take(), Some(SignalState::Working));

    notify("01a13c5a-af1e-78b3-bcc4-39027c5ecea9", "Generate a concise, single-line task title");
    assert_eq!(take(), None, "the title thread finishing is not the turn finishing");

    let sub = "01a13c5a-bdbb-7672-b29a-0f56b7557bdb";
    hook(&format!(
        r#"{{"session_id":"{main}","turn_id":"b","agent_id":"{sub}","agent_type":"default","hook_event_name":"UserPromptSubmit"}}"#
    ));
    hook(&format!(
        r#"{{"session_id":"{main}","turn_id":"b","hook_event_name":"SubagentStop","agent_id":"{sub}"}}"#
    ));
    notify(sub, "Read app.py");
    assert_eq!(take(), None, "a subagent finishing is not the turn finishing");

    hook(&format!(r#"{{"session_id":"{main}","turn_id":"a","hook_event_name":"Stop"}}"#));
    assert_eq!(take(), Some(SignalState::Done));
    // The conversation's own notify for the SAME turn ~0.6s later is a repeat.
    run_hook_command(
        &format!("sh '{script}' '{{\"type\":\"agent-turn-complete\",\"thread-id\":\"{main}\",\"turn-id\":\"a\"}}'"),
        "",
    );
    assert_eq!(take(), None, "one done per turn");
    // The next turn's end still counts.
    hook(&format!(r#"{{"session_id":"{main}","turn_id":"c","hook_event_name":"Stop"}}"#));
    assert_eq!(take(), Some(SignalState::Done));
    let _ = std::fs::remove_dir_all(&dir);
}

// `$ <command>` in the task pane opens a shell in the checkout with the command
// typed in; the row is a plain process, not an agent.
#[cfg(not(windows))]
#[test]
fn dollar_input_opens_a_shell_running_the_command() {
    let _env = env_guard();
    let dir = unique_test_repo("dollar-shell");
    let old_shell = std::env::var_os("SHELL");
    std::env::set_var("SHELL", "/bin/sh");

    let mut app = App::new();
    app.cwd = dir.clone();
    app.start_task_from_input("$ echo rudder-shell-$((40 + 2))");
    let mut seen = false;
    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline && !seen {
        app.poll_agents();
        if let Some(terminal) = app.agents.last_mut().and_then(|run| run.terminal.as_mut()) {
            let _ = terminal.drain_output();
            seen = terminal
                .visible_lines_snapshot()
                .iter()
                .any(|line| line.contains("rudder-shell-42"));
        }
        std::thread::sleep(Duration::from_millis(50));
    }
    let run = app.agents.last().expect("a row for the shell");
    let (label, plain, status) = (run.task.clone(), run.plain_process, run.status);

    // A bare `$` is just a shell.
    app.start_task_from_input("$");
    let bare = app.agents.last().map(|run| run.task.clone());

    // `$ export ...` runs in the shell; it is not filed as shared context.
    app.start_task_from_input("$ export DEMO_API_TOKEN=abc123");
    let shared = std::fs::read_to_string(dir.join("RUDDER_SHARED.md")).unwrap_or_default();

    for run in &mut app.agents {
        run.terminal = None;
    }
    match old_shell {
        Some(value) => std::env::set_var("SHELL", value),
        None => std::env::remove_var("SHELL"),
    }
    let _ = std::fs::remove_dir_all(&dir);

    assert!(seen, "the shell ran the command (it evaluated the arithmetic)");
    assert_eq!(label, "$ echo rudder-shell-$((40 + 2))");
    assert!(plain, "a shell pane is a plain process, not an agent");
    assert_eq!(status, AgentStatus::Running);
    assert_eq!(bare.as_deref(), Some("$ shell"));
    assert!(!shared.contains("abc123"), "shell input is not shared context: {shared}");
}

// The phone's key strip and terminal view: named keys reach a live pane, and
// its screen is mirrored to screen.txt only while something watches it.
#[cfg(not(windows))]
#[test]
fn phone_keys_and_watched_screen_mirror() {
    let _env = env_guard();
    let dir = unique_test_repo("phone-keys");
    let old_shell = std::env::var_os("SHELL");
    std::env::set_var("SHELL", "/bin/sh");
    let mut app = App::new();
    app.cwd = dir.clone();
    app.start_task_from_input("$");
    let id = app.agents.last().unwrap().id.clone();

    let unknown = app.deliver_keys_request(&id, "hyperspace");
    // Type `echo phone-$((6*7))` one key at a time is not possible with named
    // keys alone, so paste the command and press the named Enter key.
    let _ = app.agents.last_mut().unwrap().terminal.as_mut().unwrap().write_input(b"echo phone-$((6*7))");
    let delivered = app.deliver_keys_request(&id, "enter");

    let run_dir = native_run_dir(&dir, &id);
    std::fs::create_dir_all(&run_dir).unwrap();
    app.write_watched_screens();
    let unwatched = run_dir.join("screen.txt").exists();
    std::fs::write(run_dir.join("screen.watch"), "").unwrap();
    let mut screen = String::new();
    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline && !screen.contains("phone-42") {
        app.poll_agents();
        if let Some(terminal) = app.agents.last_mut().and_then(|run| run.terminal.as_mut()) {
            let _ = terminal.drain_output();
        }
        app.write_watched_screens();
        screen = std::fs::read_to_string(run_dir.join("screen.txt")).unwrap_or_default();
        std::thread::sleep(Duration::from_millis(50));
    }

    for run in &mut app.agents {
        run.terminal = None;
    }
    match old_shell {
        Some(value) => std::env::set_var("SHELL", value),
        None => std::env::remove_var("SHELL"),
    }
    let _ = std::fs::remove_dir_all(&dir);

    assert!(matches!(unknown, SteerDelivery::Failed(_)), "unknown keys are refused");
    assert!(matches!(delivered, SteerDelivery::Delivered), "enter reached the live pane");
    assert!(!unwatched, "nothing is mirrored while nobody watches");
    assert!(screen.contains("phone-42"), "the watched screen shows the command's output: {screen}");
}

