/// The home machine stops when idle, and every live row comes back Paused with
/// no process, so its Claude Remote Control session reads offline in the app
/// until someone steers it. On boot the home dashboard reopens those sessions
/// itself: `--resume` with the saved session, and no new turn. A row you
/// stopped stays stopped, and nothing of this happens off the home machine.
#[cfg(not(windows))]
#[test]
fn home_machine_boot_reopens_paused_rows_without_a_new_turn() {
    let _env = env_guard();
    let dir = unique_test_repo("home-boot-reopen");
    let args_log = dir.join("args.log");
    let fake = dir.join("fake-claude.sh");
    write_fake_bin(
        &fake,
        &format!("#!/bin/sh\necho \"$@\" >> '{}'\nsleep 5\n", args_log.display()),
    );
    std::env::set_var("RUDDER_CLAUDE_BIN", &fake);
    std::env::set_var("RUDDER_HOME", dir.join("home"));

    // The env is read once, at construction.
    std::env::set_var("RUDDER_CLOUD_RUNTIME", "home");
    assert!(home_runtime_from_env());
    std::env::set_var("RUDDER_CLOUD_RUNTIME", "fly");
    assert!(!home_runtime_from_env());
    std::env::remove_var("RUDDER_CLOUD_RUNTIME");
    assert!(!home_runtime_from_env());

    let build = |home: bool| {
        let mut app = App::new();
        app.cwd = dir.clone();
        app.home_runtime = home;
        app.agents.clear();
        let mut main = test_agent_run(MAIN_AGENT_ID, "own the checkout");
        main.mode = AgentMode::Main;
        main.cwd = dir.clone();
        main.terminal = None;
        main.status = AgentStatus::Paused;
        main.session_id = Some("11111111-2222-3333-4444-555555555555".to_string());
        app.agents.push(main);
        let mut stopped = test_agent_run("stopped-worker", "you stopped me");
        stopped.cwd = dir.clone();
        stopped.terminal = None;
        stopped.status = AgentStatus::Stopped;
        stopped.session_id = Some("stopped-session".to_string());
        app.agents.push(stopped);
        let mut gone = test_agent_run("gone-worker", "workspace swept");
        gone.cwd = dir.join("no-such-workspace");
        gone.terminal = None;
        gone.status = AgentStatus::Paused;
        gone.session_id = Some("gone-session".to_string());
        app.agents.push(gone);
        app
    };

    // Off the home machine: nothing relaunches.
    let mut app = build(false);
    app.poll_agents();
    assert!(app.agents.iter().all(|run| run.terminal.is_none()));
    assert_eq!(app.agents[0].status, AgentStatus::Paused);

    // On it: the paused main row resumes its session, once.
    let mut app = build(true);
    app.poll_agents();
    app.poll_agents();
    // Generous: macOS vets a freshly written executable on its first exec.
    let deadline = Instant::now() + Duration::from_secs(15);
    while fs::read_to_string(&args_log).map_or(true, |text| !text.contains('\n'))
        && Instant::now() < deadline
    {
        std::thread::sleep(Duration::from_millis(20));
    }
    let main_live = app.agents[0].terminal.is_some();
    let main_status = app.agents[0].status;
    let main_turns = app.agents[0].turns.len();
    let stopped_live = app.agents[1].terminal.is_some();
    let gone_live = app.agents[2].terminal.is_some();
    for run in app.agents.iter_mut() {
        if let Some(mut terminal) = run.terminal.take() {
            terminal.request_termination();
        }
    }
    let args = fs::read_to_string(&args_log).unwrap_or_default();
    let _ = fs::remove_dir_all(&dir);

    assert!(main_live, "the paused main row is live again");
    assert_eq!(main_status, AgentStatus::Running, "as it was before the stop");
    assert_eq!(main_turns, 1, "no new turn was recorded");
    assert!(!stopped_live, "an explicit stop is respected");
    assert!(!gone_live, "a row whose workspace is gone is left alone");
    let lines: Vec<&str> = args.lines().collect();
    assert_eq!(lines.len(), 1, "exactly one relaunch: {args:?}");
    assert!(
        lines[0].contains("--resume 11111111-2222-3333-4444-555555555555"),
        "resumes the saved session: {args:?}"
    );
    assert!(
        lines[0].contains("--settings"),
        "completion hooks are wired: {args:?}"
    );
    assert!(
        !lines[0].contains("own the checkout"),
        "no prompt is sent: {args:?}"
    );
}

#[test]
fn home_machine_boot_reopens_an_idle_done_main_row_and_keeps_it_done() {
    let _env = env_guard();
    let dir = unique_test_repo("home-boot-reopen-done");
    let args_log = dir.join("args.log");
    let fake = dir.join("fake-claude.sh");
    write_fake_bin(
        &fake,
        &format!("#!/bin/sh\necho \"$@\" >> '{}'\nsleep 5\n", args_log.display()),
    );
    std::env::set_var("RUDDER_CLAUDE_BIN", &fake);
    std::env::set_var("RUDDER_HOME", dir.join("home"));

    let mut app = App::new();
    app.cwd = dir.clone();
    app.home_runtime = true;
    app.agents.clear();
    let mut main = test_agent_run(MAIN_AGENT_ID, "own the checkout");
    main.mode = AgentMode::Main;
    main.cwd = dir.clone();
    main.terminal = None;
    main.status = AgentStatus::Done;
    main.session_id = Some("11111111-2222-3333-4444-666666666666".to_string());
    app.agents.push(main);
    let mut worker = test_agent_run("done-worker", "finished, awaiting merge");
    worker.cwd = dir.clone();
    worker.terminal = None;
    worker.status = AgentStatus::Done;
    worker.session_id = Some("done-worker-session".to_string());
    app.agents.push(worker);

    app.poll_agents();
    let deadline = Instant::now() + Duration::from_secs(15);
    while fs::read_to_string(&args_log).map_or(true, |text| !text.contains('\n'))
        && Instant::now() < deadline
    {
        std::thread::sleep(Duration::from_millis(20));
    }
    let main_live = app.agents[0].terminal.is_some();
    let main_status = app.agents[0].status;
    let worker_live = app.agents[1].terminal.is_some();
    for run in app.agents.iter_mut() {
        if let Some(mut terminal) = run.terminal.take() {
            terminal.request_termination();
        }
    }
    let args = fs::read_to_string(&args_log).unwrap_or_default();
    let _ = fs::remove_dir_all(&dir);

    assert!(main_live, "the idle main chat is reachable again");
    assert_eq!(main_status, AgentStatus::Done, "it ran no turn, so it is still done");
    assert!(!worker_live, "a done worker is left for review");
    assert!(args.contains("--resume 11111111-2222-3333-4444-666666666666"), "{args:?}");
}

#[test]
fn claude_hooks_report_the_live_session_and_the_row_follows_it() {
    let _env = env_guard();
    let dir = unique_test_repo("claude-session-follow");
    std::env::set_var("RUDDER_HOME", dir.join("home"));
    let run_id = "follow-run";
    let signal = signals::signal_path(run_id).expect("signal path");

    // The hooks Rudder installs write the session id from the hook's stdin.
    let settings: serde_json::Value =
        serde_json::from_str(&signals::claude_settings_json(&signal, false)).unwrap();
    for event in ["Stop", "UserPromptSubmit"] {
        let commands: Vec<String> = settings["hooks"][event][0]["hooks"]
            .as_array()
            .unwrap()
            .iter()
            .map(|hook| hook["command"].as_str().unwrap().to_string())
            .collect();
        let session_hook = commands
            .iter()
            .find(|command| command.contains("session_id"))
            .unwrap_or_else(|| panic!("{event} reports the session: {commands:?}"));
        fs::create_dir_all(signal.parent().unwrap()).unwrap();
        let mut child = Command::new("/bin/sh")
            .arg("-c")
            .arg(session_hook)
            .stdin(Stdio::piped())
            .spawn()
            .unwrap();
        child
            .stdin
            .take()
            .unwrap()
            .write_all(br#"{"session_id": "3709e163-3eb4-489f-a5a9-15353f4aa59b","hook_event_name":"Stop"}"#)
            .unwrap();
        assert!(child.wait().unwrap().success());
        assert_eq!(
            signals::read_claude_session(run_id).as_deref(),
            Some("3709e163-3eb4-489f-a5a9-15353f4aa59b"),
            "{event}"
        );
    }

    let mut app = App::new();
    app.cwd = dir.clone();
    app.agents.clear();
    let mut run = test_agent_run(run_id, "chat");
    run.cwd = dir.clone();
    run.terminal = None;
    run.session_id = Some("a29953b9-bed6-4a56-a0c4-55be8e07188b".to_string());
    app.agents.push(run);
    app.adopt_reported_claude_sessions();
    let adopted = app.agents[0].session_id.clone();
    let _ = fs::remove_dir_all(&dir);
    assert_eq!(adopted.as_deref(), Some("3709e163-3eb4-489f-a5a9-15353f4aa59b"));
}

/// `rudder cloud` reconnecting sends the dashboard a SIGWINCH at the SAME size
/// (the relay's replay is only the tail of the output, so the laptop needs the
/// whole picture again). A same-size resize changes nothing ratatui can see, so
/// it must force every cell out, painted over in place rather than cleared.
#[test]
fn a_same_size_sigwinch_repaints_every_cell_in_place() {
    use ratatui::backend::CrosstermBackend;
    use ratatui::layout::Rect;
    use ratatui::widgets::Paragraph;
    use ratatui::{Terminal, TerminalOptions, Viewport};
    use std::sync::{Arc, Mutex};

    #[derive(Clone, Default)]
    struct Sink(Arc<Mutex<Vec<u8>>>);
    impl std::io::Write for Sink {
        fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
            self.0.lock().unwrap().extend_from_slice(bytes);
            Ok(bytes.len())
        }
        fn flush(&mut self) -> std::io::Result<()> {
            Ok(())
        }
    }

    let mut app = App::new();
    assert!(!handle_event(&mut app, Event::Resize(80, 24)));
    assert!(app.repaint_all, "a SIGWINCH asks for the whole picture");

    let sink = Sink::default();
    let mut terminal = Terminal::with_options(
        CrosstermBackend::new(sink.clone()),
        TerminalOptions {
            viewport: Viewport::Fixed(Rect::new(0, 0, 20, 3)),
        },
    )
    .unwrap();
    let draw = |terminal: &mut Terminal<CrosstermBackend<Sink>>| {
        terminal
            .draw(|frame| frame.render_widget(Paragraph::new("hello\nworld"), frame.area()))
            .unwrap();
        String::from_utf8_lossy(&std::mem::take(&mut *sink.0.lock().unwrap())).into_owned()
    };
    assert!(draw(&mut terminal).contains("hello"));
    let unchanged = draw(&mut terminal);
    assert!(
        !unchanged.contains("hello"),
        "an unchanged frame redraws nothing: {unchanged:?}"
    );
    force_full_repaint(&mut terminal);
    let forced = draw(&mut terminal);
    assert!(
        forced.contains("hello") && forced.contains("world"),
        "every cell is drawn again: {forced:?}"
    );
    assert!(
        !forced.contains("\x1b[2J"),
        "painted over in place, never cleared: {forced:?}"
    );
}

#[test]
fn cloud_claude_settings_carry_the_phone_permission_hook() {
    let base = crate::signals::claude_settings_json(Path::new("/tmp/sig/run.json"), false);
    let json = crate::signals::with_permission_hook(
        &base,
        Path::new("/home/rudder/.rudder/signals/permission-hook.mjs"),
        Path::new("/home/rudder/.rudder/signals/run.asks"),
    );
    let value: serde_json::Value = serde_json::from_str(&json).unwrap();
    let hook = &value["hooks"]["PermissionRequest"][0]["hooks"][0];
    assert_eq!(
        hook["command"],
        "node '/home/rudder/.rudder/signals/permission-hook.mjs' '/home/rudder/.rudder/signals/run.asks'"
    );
    assert_eq!(hook["timeout"], 86400);
    // The lifecycle hooks are untouched.
    assert!(value["hooks"]["Stop"].is_array());
    assert!(crate::signals::PERMISSION_HOOK_JS.contains("PermissionRequest"));
}

#[test]
fn sync_subcommands_appear_only_in_the_named_family() {
    let mut app = App::new();
    app.task_input = "/syn".to_string();
    let labels: Vec<String> = suggestions_for(&app).into_iter().map(|s| s.label).collect();
    assert_eq!(labels.first().map(String::as_str), Some("/sync"));
    assert!(!labels.iter().any(|l| l == "/sync move" || l == "/sync all"));
    app.task_input = "/sync ".to_string();
    let labels: Vec<String> = suggestions_for(&app).into_iter().map(|s| s.label).collect();
    assert!(labels.iter().any(|l| l == "/sync move"));
    assert!(labels.iter().any(|l| l == "/sync all"));
}

fn gods_view_app(count: usize) -> App {
    let mut app = App::new();
    for index in 0..count {
        let mut run = test_agent_run(&format!("run-{index}"), &format!("tile task {index}"));
        run.task_summary = format!("tile task {index}");
        run.status = AgentStatus::Running;
        app.agents.push(run);
    }
    app
}

#[test]
fn alt_g_opens_and_closes_gods_view() {
    let mut app = gods_view_app(2);
    app.focus = FocusPane::Task;
    app.handle_key(KeyEvent::new(KeyCode::Char('g'), KeyModifiers::ALT));
    assert!(app.gods_view, "Alt+G opens god's view");
    app.handle_key(KeyEvent::new(KeyCode::Char('g'), KeyModifiers::ALT));
    assert!(!app.gods_view, "Alt+G again closes it");
    assert!(app.task_input.is_empty(), "the chord never types into the task bar");
}

#[test]
fn option_g_copyright_char_toggles_gods_view() {
    let mut app = gods_view_app(2);
    app.focus = FocusPane::Worker;
    app.handle_key(KeyEvent::new(KeyCode::Char('\u{00a9}'), KeyModifiers::NONE));
    assert!(app.gods_view);
    app.handle_key(KeyEvent::new(KeyCode::Char('\u{00a9}'), KeyModifiers::NONE));
    assert!(!app.gods_view);
}

#[test]
fn esc_closes_gods_view_and_leader_and_nav_mode_open_it() {
    let mut app = gods_view_app(2);
    app.focus = FocusPane::Agents;
    app.handle_key(KeyEvent::new(KeyCode::Char('w'), KeyModifiers::CONTROL));
    app.handle_key(KeyEvent::new(KeyCode::Char('g'), KeyModifiers::NONE));
    assert!(app.gods_view, "^W g opens god's view");
    app.handle_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));
    assert!(!app.gods_view, "Esc closes it");

    app.handle_key(KeyEvent::new(KeyCode::Char('g'), KeyModifiers::CONTROL));
    assert!(app.nav_mode);
    app.handle_key(KeyEvent::new(KeyCode::Char('g'), KeyModifiers::NONE));
    assert!(app.gods_view, "nav mode g opens god's view");
}

